class Solution:
    def maximalSquare(self, matrix: List[List[str]]) -> int:
        if not matrix or not matrix[0]:
            return 0
        n = len(matrix[0])
        dp = [0] * (n + 1)
        best = 0
        for row in matrix:
            prev = 0
            for j in range(1, n + 1):
                up = dp[j]
                if row[j - 1] == '1':
                    dp[j] = min(dp[j], dp[j - 1], prev) + 1
                    if dp[j] > best:
                        best = dp[j]
                else:
                    dp[j] = 0
                prev = up
        return best * best

