#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int maximalSquare(char** matrix, int matrixSize, int* matrixColSize) {
    if (matrixSize == 0 || matrixColSize == NULL || matrixColSize[0] == 0) return 0;

    int n = matrixColSize[0];
    int* dp = (int*)calloc((size_t)n + 1, sizeof(int));
    if (!dp) return 0;

    int best = 0;
    for (int i = 0; i < matrixSize; ++i) {
        int prev = 0;
        for (int j = 1; j <= n; ++j) {
            int up = dp[j];
            if (matrix[i][j - 1] == '1') {
                int v = dp[j] < dp[j - 1] ? dp[j] : dp[j - 1];
                if (prev < v) v = prev;
                dp[j] = v + 1;
                if (dp[j] > best) best = dp[j];
            } else {
                dp[j] = 0;
            }
            prev = up;
        }
    }

    free(dp);
    return best * best;
}

static char** parseMatrix(const char* s, int* rowsOut, int** colsOut) {
    char** matrix = (char**)malloc(300 * sizeof(char*));
    int* cols = (int*)malloc(300 * sizeof(int));
    if (!matrix || !cols) {
        free(matrix);
        free(cols);
        *rowsOut = 0;
        *colsOut = NULL;
        return NULL;
    }

    int depth = 0, row = -1, col = 0;
    for (int i = 0; s[i] != '\0'; ++i) {
        if (s[i] == '[') {
            ++depth;
            if (depth == 3) {
                ++row;
                col = 0;
                matrix[row] = (char*)malloc(300);
                cols[row] = 0;
            }
        } else if (s[i] == ']') {
            if (depth == 3 && row >= 0) cols[row] = col;
            --depth;
        } else if (s[i] == '"' && depth == 3 && s[i + 1] != '\0') {
            if (row >= 0 && col < 300) matrix[row][col++] = s[i + 1];
            i += 2;
        }
    }

    *rowsOut = row + 1;
    *colsOut = cols;
    return matrix;
}

