    public int maximalSquare(char[][] matrix) {
        if (matrix == null || matrix.length == 0 || matrix[0].length == 0) {
            return 0;
        }

        int n = matrix[0].length;
        int[] dp = new int[n + 1];
        int best = 0;

        for (char[] row : matrix) {
            int prev = 0;
            for (int j = 1; j <= n; j++) {
                int up = dp[j];
                if (row[j - 1] == '1') {
                    dp[j] = Math.min(Math.min(dp[j], dp[j - 1]), prev) + 1;
                    best = Math.max(best, dp[j]);
                } else {
                    dp[j] = 0;
                }
                prev = up;
            }
        }
        return best * best;
    }
}

