public class Main {
    private static char[][] parseMatrix(String s) {
        List<char[]> rows = new ArrayList<>();
        List<Character> current = null;
        int depth = 0;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '[') {
                depth++;
                if (depth == 3) current = new ArrayList<>();
            } else if (c == ']') {
                if (depth == 3 && current != null) {
                    char[] row = new char[current.size()];
                    for (int j = 0; j < current.size(); j++) row[j] = current.get(j);
                    rows.add(row);
                    current = null;
                }
                depth--;
            } else if (c == '"' && depth == 3 && i + 2 < s.length()) {
                char value = s.charAt(i + 1);
                if (current != null && (value == '0' || value == '1')) {
                    current.add(value);
                }
                i += 2;
            }
        }
        return rows.toArray(new char[0][]);
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        char[][] matrix = parseMatrix(line.trim());
        System.out.println(new Solution().maximalSquare(matrix));
    }
